alter table public.cars add column if not exists is_premium boolean not null default false;
alter table public.cars add column if not exists is_commercial boolean not null default false;
create index if not exists cars_is_premium_idx on public.cars(is_premium) where is_premium=true;
create index if not exists cars_is_commercial_idx on public.cars(is_commercial) where is_commercial=true;
create or replace function public.sync_car_category_items(p_car_id uuid) returns void language plpgsql security definer set search_path = '' as $$ declare v_car public.cars%rowtype; v_category_id uuid; begin select * into v_car from public.cars where id=p_car_id; if not found then delete from public.car_category_items where car_id=p_car_id; return; end if; delete from public.car_category_items where car_id=p_car_id; if v_car.is_featured then select id into v_category_id from public.car_categories where key='popular' limit 1; if v_category_id is not null then insert into public.car_category_items(category_id,car_id) values(v_category_id,p_car_id) on conflict do nothing; end if; end if; if v_car.old_price is not null and v_car.old_price>v_car.price then select id into v_category_id from public.car_categories where key='discounts' limit 1; if v_category_id is not null then insert into public.car_category_items(category_id,car_id) values(v_category_id,p_car_id) on conflict do nothing; end if; end if; if lower(coalesce(v_car.fuel_type,'')) like '%electric%' or lower(coalesce(v_car.fuel_type,'')) like '%elektr%' then select id into v_category_id from public.car_categories where key='electric' limit 1; if v_category_id is not null then insert into public.car_category_items(category_id,car_id) values(v_category_id,p_car_id) on conflict do nothing; end if; end if; if lower(coalesce(v_car.fuel_type,'')) like '%hybrid%' or lower(coalesce(v_car.fuel_type,'')) like '%gibrid%' then select id into v_category_id from public.car_categories where key='hybrid' limit 1; if v_category_id is not null then insert into public.car_category_items(category_id,car_id) values(v_category_id,p_car_id) on conflict do nothing; end if; end if; if v_car.is_premium then select id into v_category_id from public.car_categories where key='premium' limit 1; if v_category_id is not null then insert into public.car_category_items(category_id,car_id) values(v_category_id,p_car_id) on conflict do nothing; end if; end if; if v_car.is_commercial then select id into v_category_id from public.car_categories where key='commercial' limit 1; if v_category_id is not null then insert into public.car_category_items(category_id,car_id) values(v_category_id,p_car_id) on conflict do nothing; end if; end if; if exists (select 1 from public.financing_programs p join public.banks b on b.id=p.bank_id where p.is_active and coalesce(p.interest_rate,-1)=0 and b.is_active and coalesce(b.integration_status,'information_only')<>'disabled' and (p.applicable_brand_id is null or p.applicable_brand_id=v_car.brand_id) and (p.applicable_model_id is null or p.applicable_model_id=v_car.model_id) and (p.min_car_price is null or p.min_car_price<=v_car.price) and (p.max_car_price is null or p.max_car_price>=v_car.price) and (not exists(select 1 from public.financing_program_cars pc where pc.financing_program_id=p.id) or exists(select 1 from public.financing_program_cars pc where pc.financing_program_id=p.id and pc.car_id=p_car_id)) and (not exists(select 1 from public.financing_program_dealers pd where pd.financing_program_id=p.id) or (v_car.dealer_id is not null and exists(select 1 from public.financing_program_dealers pd where pd.financing_program_id=p.id and pd.dealer_id=v_car.dealer_id)))) then select id into v_category_id from public.car_categories where key='installment' limit 1; if v_category_id is not null then insert into public.car_category_items(category_id,car_id) values(v_category_id,p_car_id) on conflict do nothing; end if; end if; end; $$;
create or replace function public.sync_car_category_items_trigger() returns trigger language plpgsql security definer set search_path = '' as $$ begin perform public.sync_car_category_items(NEW.id); return NEW; end; $$;
create or replace function public.sync_all_car_category_items() returns trigger language plpgsql security definer set search_path = '' as $$ begin perform public.sync_car_category_items(id) from public.cars; return null; end; $$;
drop trigger if exists cars_sync_category_items on public.cars; create trigger cars_sync_category_items after insert or update of brand_id,model_id,dealer_id,price,old_price,fuel_type,is_featured,is_premium,is_commercial,is_active on public.cars for each row execute function public.sync_car_category_items_trigger();
drop trigger if exists financing_programs_sync_category_items on public.financing_programs; create trigger financing_programs_sync_category_items after insert or update or delete on public.financing_programs for each statement execute function public.sync_all_car_category_items();
drop trigger if exists financing_program_cars_sync_category_items on public.financing_program_cars; create trigger financing_program_cars_sync_category_items after insert or update or delete on public.financing_program_cars for each statement execute function public.sync_all_car_category_items();
drop trigger if exists financing_program_dealers_sync_category_items on public.financing_program_dealers; create trigger financing_program_dealers_sync_category_items after insert or update or delete on public.financing_program_dealers for each statement execute function public.sync_all_car_category_items();
drop trigger if exists dealers_sync_category_items on public.dealers; create trigger dealers_sync_category_items after insert or update or delete on public.dealers for each statement execute function public.sync_all_car_category_items();
select public.sync_car_category_items(id) from public.cars;
